@@ -48,7 +48,7 @@ export interface Router<T> {
    * @param path - The path to match.
    * @returns The result of the match.
    */
-  match(method: string, path: string): Result<T>
+  matchRoute(method: string, path: string): Result<T>
 }

 /**
diff --git a/src/router/reg-exp-router/matcher.ts b/src/router/reg-exp-router/matcher.ts
index cfa862b6..ae023fc2 100644
--- a/src/router/reg-exp-router/matcher.ts
+++ b/src/router/reg-exp-router/matcher.ts
@@ -26,8 +26,8 @@ export function match<R extends Router<T>, T>(this: R, method: string, path: str

     const index = match.indexOf('', 1)
     return [matcher[1][index], match]
-  }) as Router<T>['match']
+  }) as Router<T>['matchRoute']

-  this.match = match
+  this.matchRoute = match
   return match(method, path)
 }
diff --git a/src/router/smart-router/router.ts b/src/router/smart-router/router.ts
index 9ec464da..3ce6d0b2 100644
--- a/src/router/smart-router/router.ts
+++ b/src/router/smart-router/router.ts
@@ -18,7 +18,7 @@ export class SmartRouter<T> implements Router<T> {
     this.#routes.push([method, path, handler])
   }

-  match(method: string, path: string): Result<T> {
+  matchRoute(method: string, path: string): Result<T> {
     if (!this.#routes) {
       throw new Error('Fatal error')
     }
@@ -35,7 +35,7 @@ export class SmartRouter<T> implements Router<T> {
         for (let i = 0, len = routes.length; i < len; i++) {
           router.add(...routes[i])
         }
-        res = router.match(method, path)
+        res = router.matchRoute(method, path)
       } catch (e) {
         if (e instanceof UnsupportedPathError) {
           continue
@@ -43,7 +43,7 @@ export class SmartRouter<T> implements Router<T> {
         throw e
       }

-      this.match = router.match.bind(router)
+      this.matchRoute = router.matchRoute.bind(router)
       this.#routers = [router]
       this.#routes = undefined
       break

